#!/usr/bin/env python3
"""Deterministic, original SVG figures calculated from sealed experimental results.

--check compares generated bytes with committed figures without writing.
No invented metrics, external graphics, private RPC, network or fonts.
"""
import argparse
import json
from pathlib import Path
from xml.sax.saxutils import escape

ROOT=Path(__file__).resolve().parents[1]
FIG=ROOT/"figures"
RESULTS=ROOT/"evidence/derived/2026-11-04-confirmatory-results.json"
TIMES=ROOT/"evidence/derived/2026-11-04-fault-retry-timelines.json"
INK="#172536"; MUTED="#637285"; BLUE="#33779b"; ORANGE="#bf752e"
BG="#ffffff"; LINE="#d7dee5"

def canvas(w,h,body):
    return (
      '<svg xmlns="http://www.w3.org/2000/svg" width="'+str(w)+'" height="'+str(h)+
      '" viewBox="0 0 '+str(w)+' '+str(h)+'" role="img">\n'+
      '<rect width="'+str(w)+'" height="'+str(h)+'" fill="'+BG+'"/>\n'+
      '\n'.join(body)+'\n</svg>\n'
    )
def txt(x,y,s,size=18,weight=400,color=INK,anchor="start"):
    return f'<text x="{x}" y="{y}" font-size="{size}" font-weight="{weight}" fill="{color}" text-anchor="{anchor}" font-family="Arial,Helvetica,sans-serif">{escape(str(s))}</text>'
def rect(x,y,w,h,color,r=0):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{color}"/>'
def rule(x1,y1,x2,y2,color=LINE,width=1):
    return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{color}" stroke-width="{width}"/>'
def figure_counts():
    r=json.loads(RESULTS.read_text())
    assert r["trial_count"]==12
    cond=r["conditions"]
    labels={
      "C0":"Normal delivery",
      "C1":"Rejected application",
      "F1":"Interrupted processing",
      "F2":"Interrupted completion"
    }
    body=[
      txt(58,68,"Settlement and application effects",30,650),
      txt(58,100,"Three measured transfers per condition  |  locally operated Enygma environment",16,400,MUTED),
      rect(58,140,18,18,BLUE,3),txt(85,155,"Destination mints",16,400),
      rect(290,140,18,18,ORANGE,3),txt(318,155,"Application executions",16,400),
      rule(58,505,1030,505,INK,1.6),
    ]
    base=505
    scale=112
    for j,code in enumerate(["C0","C1","F1","F2"]):
        n=cond[code]["n"]
        minted=cond[code]["destination_mints"]
        apps=cond[code]["app_effects"]
        assert n==3 and len(minted)==3 and len(apps)==3
        assert len(set(minted))==1 and len(set(apps))==1
        m,a=minted[0],apps[0]
        x=85+j*243
        body.append(rect(x,base-scale*m,64,scale*m,BLUE,4))
        body.append(rect(x+78,base-scale*a,64,scale*a,ORANGE,4))
        body.append(txt(x+32,base-scale*m-12,str(m),19,650,BLUE,"middle"))
        body.append(txt(x+110,base-scale*a-12,str(a),19,650,ORANGE,"middle"))
        body.append(txt(x+72,541,code,17,650,INK,"middle"))
        body.append(txt(x+72,566,labels[code],14,400,MUTED,"middle"))
    body.append(txt(58,615,"Observation: settlement minting stayed singular during both retry conditions.",16,500,INK))
    body.append(txt(58,640,"Source: sealed 12-trial dataset. Counts represent local contracts, not public-chain receipts.",14,400,MUTED))
    return canvas(1100,670,body)
def figure_timing():
    r=json.loads(TIMES.read_text())
    trials=r["trials"]
    assert len(trials)==6
    values={t["trial"]:t["retry_minus_first_block_seconds"] for t in trials}
    assert set(values)=={"F1-01","F1-02","F1-03","F2-01","F2-02","F2-03"}
    body=[
      txt(58,68,"Time between destination executions",30,650),
      txt(58,100,"Difference between local destination block timestamps for the first and retry transaction",16,400,MUTED),
    ]
    x_min,x_max=25,35
    x0,x1=345,990
    def x(s):return x0+(s-x_min)*(x1-x0)/(x_max-x_min)
    body.append(rule(x0,165,x0,516,LINE,1))
    body.append(rule(x0,517,x1,517,INK,1.5))
    for second in range(25,36):
        xx=x(second)
        if second%2==1:body.append(rule(xx,165,xx,517,LINE,0.8))
        body.append(txt(xx,545,str(second),15,400,MUTED,"middle"))
    body.append(txt(667,578,"Elapsed seconds",17,500,INK,"middle"))
    for i,name in enumerate(sorted(values)):
        value=values[name]
        assert 0<=value<=1000
        yy=205+i*54
        body.append(txt(58,yy+6,name,17,600))
        body.append(rule(x0,yy,x1,yy,"#eef2f5",1))
        body.append('<circle cx="'+str(x(value))+'" cy="'+str(yy)+'" r="11" fill="'+(BLUE if name.startswith("F1") else ORANGE)+'"/>')
        body.append(txt(x(value)+19,yy+6,str(value)+" s",17,600))
    body.append(txt(58,634,"F1 = interruption after dispatch; F2 = interruption before completion.",15,500,INK))
    body.append(txt(58,657,"These are block timestamp differences on one local network, not independent wall-clock measurements.",13,400,MUTED))
    return canvas(1100,690,body)

def main():
    p=argparse.ArgumentParser()
    p.add_argument("--check",action="store_true")
    a=p.parse_args()
    target={
      "enygma-application-effects.svg":figure_counts(),
      "enygma-retry-intervals.svg":figure_timing()
    }
    FIG.mkdir(exist_ok=True)
    for name,content in target.items():
        path=FIG/name
        if a.check:
            if not path.is_file() or path.read_text()!=content:
                raise SystemExit("FIGURE DOES NOT MATCH MEASURED INPUTS: "+name)
            print("FIGURE_VERIFIED",name)
        else:
            if path.exists():raise SystemExit("refusing to overwrite existing visual: "+name)
            path.write_text(content,encoding="utf-8")
            print("FIGURE_CREATED",name,"bytes",len(content))
if __name__=="__main__":main()
